async function ensurePostgresSchema(pool) {
  if (!postgresSchemaPromise) {
    postgresSchemaPromise = (async () => {
      await pool.query(`
      CREATE TABLE IF NOT EXISTS story_state (
        state_key TEXT PRIMARY KEY,
        data JSONB NOT NULL,
