  })

  test('未知状态名被拒绝', async () => {
    await assert.rejects(() => readWorkspaceState(workspace, 'unknown'), /未知的工作区状态/)
  })
})

describe('目录树', () => {
  test('返回文件与目录，跳过点文件', async () => {
    await writeWorkspaceText(workspace, '正文/第001章_一.md', '一')
