async function draftMapForWorkspace(project) {
  const root = currentWorkspaceRoot()
  if (!root) return {}
  const workspace = { root, meta: null }
  const { chapters } = await listChapters(workspace)
  const byPath = new Map(chapters.map((chapter) => [chapter.path, chapter]))
  const drafts = {}
  for (const record of project.chapters || []) {
    const path = record.path || chapterStoryFilePath(record)
    if (!byPath.has(path)) continue
    const file = await readWorkspaceText(workspace, path).catch(() => null)
    drafts[String(record.id)] = file?.content || ''
  }
  return drafts
}

