// 本地工作区主界面
// ---------------------------------------------------------------
// 设计取舍（与产品方向一致）：
//   - 文件树就是结构，App 不规定模型把文件写到哪；skills 负责约定。
//   - 左侧：工作区文件树；中间：Markdown 编辑器；右侧：Agent 对话。
//   - 没有「作品 / 章节」领域模型，只有文件与当前打开的文件。
//   - Agent 的 read/write 工具直接作用于工作区磁盘，UI 只负责把结果呈现出来。
import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import {
  ArrowLeft,
  ChevronDown,
  ChevronRight,
  FileText,
  FolderOpen,
  FolderTree,
  History,
  LoaderCircle,
  Plus,
  RefreshCw,
  Send,
  Sparkles,
  Trash2,
  X,
} from 'lucide-react'
import { api } from './api'
import { writeEditorPreferences, readEditorPreferences } from './platform'

const EMPTY_TREE = []

function joinPath(dir, name) {
  return dir ? `${dir}/${name}` : name
}

function countWords(text) {
  return String(text || '').replace(/\s/g, '').length
}

function formatTime(value) {
  if (!value) return ''
  const date = new Date(value)
  if (Number.isNaN(date.getTime())) return ''
  return date.toLocaleString('zh-CN', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' })
}

function WorkspacePicker({ recent, onOpen, error, busy }) {
  const [path, setPath] = useState('')
  return (
    <div className="workspace-picker">
      <div className="workspace-picker-inner">
        <div className="workspace-picker-brand">
          <span className="brand-mark"><span>叙</span></span>
          <div>
            <h1>叙事工坊</h1>
            <p>打开一个本地文件夹开始写作。文件夹里的 Markdown 就是你的作品。</p>
          </div>
        </div>

        <form
          className="workspace-open-form"
          onSubmit={(event) => {
            event.preventDefault()
            if (!path.trim() || busy) return
            onOpen({ path: path.trim() })
          }}
        >
          <label>
            <span>工作区路径</span>
            <input
              value={path}
              onChange={(event) => setPath(event.target.value)}
              placeholder="/Users/你/Documents/我的小说"
              spellCheck={false}
              disabled={busy}
            />
          </label>
          <button type="submit" className="primary-button" disabled={busy || !path.trim()}>
            {busy ? <LoaderCircle size={16} className="spin" /> : <FolderOpen size={16} />}
            打开
          </button>
          <button
            type="button"
            className="secondary-button"
            disabled={busy || !path.trim()}
            onClick={() => onOpen({ path: path.trim(), create: true })}
          >
            <Plus size={16} />
            新建作品
          </button>
        </form>
        {error && <p className="workspace-error">{error}</p>}

        <div className="workspace-recent">
          <h2>最近打开</h2>
          {recent.length ? (
            <ul>
              {recent.map((item) => (
                <li key={item.path}>
                  <button type="button" onClick={() => onOpen({ path: item.path })} disabled={busy}>
                    <FolderTree size={15} />
                    <span className="workspace-recent-copy">
                      <strong>{item.title || item.path}</strong>
                      <small>{item.path}</small>
                    </span>
                    <span className="workspace-recent-time">{formatTime(item.openedAt)}</span>
                  </button>
                </li>
              ))}
            </ul>
          ) : (
            <p className="workspace-empty-hint">还没有打开过工作区。</p>
          )}
        </div>
      </div>
    </div>
  )
}

function TreeNode({ node, depth, currentPath, onSelect, expanded, onToggle }) {
  if (node.type === 'directory') {
    const isOpen = expanded.has(node.path)
    return (
      <li>
        <button
          type="button"
          className="tree-node tree-directory"
          style={{ paddingLeft: 8 + depth * 12 }}
          onClick={() => onToggle(node.path)}
        >
          {isOpen ? <ChevronDown size={13} /> : <ChevronRight size={13} />}
          <span>{node.name}</span>
          <small>{node.children?.length ?? 0}</small>
        </button>
        {isOpen && node.children?.length ? (
          <ul>
            {node.children.map((child) => (
              <TreeNode
                key={child.path}
                node={child}
                depth={depth + 1}
                currentPath={currentPath}
                onSelect={onSelect}
                expanded={expanded}
                onToggle={onToggle}
              />
            ))}
          </ul>
        ) : null}
      </li>
    )
  }
  return (
    <li>
      <button
        type="button"
        className={`tree-node tree-file ${node.path === currentPath ? 'active' : ''}`}
        style={{ paddingLeft: 8 + depth * 12 + 16 }}
        onClick={() => onSelect(node.path)}
