function AgentPanel({ workspace, currentPath, onApplied }) {
  const [messages, setMessages] = useState([])
  const [input, setInput] = useState('')
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')
  const endRef = useRef(null)

  useEffect(() => {
    endRef.current?.scrollIntoView({ block: 'end' })
  }, [messages.length])

  async function send() {
    const text = input.trim()
    if (!text || busy) return
    setBusy(true)
    setError('')
    setInput('')
    setMessages((current) => [...current, { role: 'user', text }])
    try {
      const response = await api.runStoryAgent({
        message: text,
        payload: {
          project_id: workspace.root,
          tool_policy: { mutateStoryData: 'allow', deleteStoryData: 'deny' },
          ...(currentPath ? { current_file: currentPath } : {}),
        },
      })
      const result = response?.result || {}
      const reply = result.summary || result.message || result.status || '已完成'
      setMessages((current) => [...current, { role: 'assistant', text: String(reply) }])
      onApplied?.()
    } catch (sendError) {
      setError(sendError.message || '请求失败')
      setMessages((current) => [...current, { role: 'assistant', text: `出错了：${sendError.message || '请求失败'}` }])
    } finally {
      setBusy(false)
    }
  }

  return (
    <aside className="agent-panel">
      <header>
        <Sparkles size={15} />
        <span>夜雨</span>
        {busy && <LoaderCircle size={13} className="spin" />}
      </header>
      <div className="agent-messages">
        {!messages.length && (
          <p className="agent-empty">
            让夜雨在这个工作区里干活。它会用文件工具直接读写 <code>正文/</code>、<code>大纲/</code> 等目录。
          </p>
        )}
        {messages.map((message, index) => (
          <div key={`${message.role}-${index}`} className={`agent-message ${message.role}`}>
            <span>{message.text}</span>
          </div>
        ))}
        {error && <p className="agent-error">{error}</p>}
        <div ref={endRef} />
      </div>
      <form
        className="agent-composer"
        onSubmit={(event) => {
          event.preventDefault()
          void send()
        }}
      >
        <textarea
          value={input}
          onChange={(event) => setInput(event.target.value)}
          placeholder={currentPath ? `就 ${currentPath} 提问，或让它继续写` : '让夜雨开始工作…'}
          rows={3}
          onKeyDown={(event) => {
            if (event.key === 'Enter' && (event.metaKey || event.ctrlKey)) {
              event.preventDefault()
              void send()
            }
          }}
        />
        <button type="submit" className="primary-button" disabled={busy || !input.trim()}>
          {busy ? <LoaderCircle size={15} className="spin" /> : <Send size={15} />}
          发送
        </button>
      </form>
    </aside>
  )
}

export default function WorkspaceApp() {
  const [loading, setLoading] = useState(true)
  const [workspace, setWorkspace] = useState(null)
  const [recent, setRecent] = useState([])
  const [openError, setOpenError] = useState('')
  const [openBusy, setOpenBusy] = useState(false)
  const [tree, setTree] = useState(EMPTY_TREE)
  const [expanded, setExpanded] = useState(() => new Set(['正文', '大纲', '设定', '追踪']))
  const [currentPath, setCurrentPath] = useState(null)
  const [content, setContent] = useState('')
  const [savedContent, setSavedContent] = useState('')
  const [fileStatus, setFileStatus] = useState('idle')
  const [fileError, setFileError] = useState('')
  const [history, setHistory] = useState([])
  const [historyOpen, setHistoryOpen] = useState(false)
  const [preferences] = useState(() => readEditorPreferences())

  const dirty = content !== savedContent

  const refreshTree = useCallback(async () => {
    if (!workspace) return
    const response = await api.getWorkspaceTree().catch(() => null)
    if (!response) return
    setTree(response.tree?.nodes || [])
  }, [workspace])

  const bootstrap = useCallback(async () => {
    setLoading(true)
    const response = await api.getWorkspace().catch(() => null)
    if (response) {
      setWorkspace(response.workspace || null)
      setRecent(response.recent || [])
    }
    setLoading(false)
  }, [])

  useEffect(() => {
    void bootstrap()
  }, [bootstrap])

  useEffect(() => {
    if (workspace) void refreshTree()
  }, [workspace, refreshTree])

  async function open(input) {
    setOpenBusy(true)
    setOpenError('')
    try {
      const response = await api.openWorkspace(input)
      setWorkspace(response.workspace)
      setCurrentPath(null)
      setContent('')
      setSavedContent('')
      const recentResponse = await api.getWorkspace().catch(() => null)
      if (recentResponse?.recent) setRecent(recentResponse.recent)
    } catch (error) {
      setOpenError(error.message || '无法打开该文件夹')
    } finally {
      setOpenBusy(false)
    }
  }

  async function selectFile(path) {
    if (dirty && path !== currentPath) {
      const confirmed = window.confirm('当前文件有未保存的修改，切换后将丢失。继续吗？')
      if (!confirmed) return
    }
    setFileStatus('loading')
    setFileError('')
    try {
      const response = await api.readWorkspaceFile(path)
      setCurrentPath(path)
      setContent(response.file.content)
      setSavedContent(response.file.content)
      setFileStatus('saved')
      setHistoryOpen(false)
    } catch (error) {
      setFileError(error.message || '读取失败')
      setFileStatus('idle')
    }
  }

  async function save() {
    if (!currentPath || !dirty) return
    setFileStatus('saving')
    try {
      await api.writeWorkspaceFile(currentPath, content)
      setSavedContent(content)
      setFileStatus('saved')
      setFileError('')
      void refreshTree()
    } catch (error) {
      setFileStatus('idle')
      setFileError(error.message || '保存失败')
    }
  }

  async function loadHistory() {
    if (!currentPath) return
    const response = await api.getWorkspaceHistory(currentPath).catch(() => null)
    setHistory(response?.snapshots || [])
    setHistoryOpen(true)
  }

  async function restoreSnapshot(snapshotId) {
    if (!currentPath) return
    const response = await api.getWorkspaceSnapshot(currentPath, snapshotId).catch(() => null)
    if (!response) return
    setContent(response.snapshot.content)
    setHistoryOpen(false)
    setFileStatus('idle')
  }

  const wordCount = useMemo(() => countWords(content), [content])

  useEffect(() => {
    if (!workspace) return
    writeEditorPreferences(preferences)
  }, [workspace, preferences])

  const toggleDir = (path) => {
    setExpanded((current) => {
      const next = new Set(current)
      if (next.has(path)) next.delete(path)
      else next.add(path)
      return next
    })
  }

  if (loading) {
    return (
      <div className="workspace-loading">
        <LoaderCircle size={20} className="spin" />
        <span>正在读取工作区</span>
      </div>
    )
  }

  if (!workspace) {
    return <WorkspacePicker recent={recent} onOpen={open} error={openError} busy={openBusy} />
  }

  return (
    <div className="workspace-shell">
      <aside className="workspace-sidebar">
        <header>
          <button type="button" className="icon-button" title="切换工作区" onClick={() => setWorkspace(null)}>
            <ArrowLeft size={15} />
          </button>
          <div>
            <strong>{workspace.meta?.title || '未命名作品'}</strong>
            <small>{workspace.root}</small>
          </div>
          <button type="button" className="icon-button" title="刷新文件树" onClick={() => void refreshTree()}>
            <RefreshCw size={14} />
          </button>
        </header>
        <ul className="workspace-tree">
          {tree.length ? (
            tree.map((node) => (
              <TreeNode
                key={node.path}
                node={node}
                depth={0}
                currentPath={currentPath}
                onSelect={selectFile}
                expanded={expanded}
                onToggle={toggleDir}
              />
            ))
          ) : (
            <li className="workspace-tree-empty">这个文件夹还是空的。让夜雨写点东西，或直接新建文件。</li>
          )}
        </ul>
        <footer>
          <span>{workspace.root}</span>
        </footer>
      </aside>

      <main className="workspace-editor">
        {currentPath ? (
          <>
            <header className="editor-header">
              <div className="editor-title">
                <FileText size={15} />
                <span>{currentPath}</span>
                {dirty && <em>未保存</em>}
              </div>
              <div className="editor-actions">
                <span className="editor-words">{wordCount} 字</span>
                {fileStatus === 'saving' && <span className="editor-status">保存中</span>}
                {fileStatus === 'saved' && !dirty && <span className="editor-status ok">已保存</span>}
                <button type="button" className="secondary-button small" onClick={() => void loadHistory()}>
                  <History size={14} />
                  历史
                </button>
                <button type="button" className="primary-button small" disabled={!dirty} onClick={() => void save()}>
                  保存
                </button>
              </div>
            </header>
            {historyOpen && (
              <div className="editor-history">
                <header>
                  <span>历史快照（{history.length}）</span>
                  <button type="button" className="icon-button" onClick={() => setHistoryOpen(false)}>
                    <X size={14} />
                  </button>
                </header>
                {history.length ? (
                  <ul>
                    {history.map((snapshot) => (
                      <li key={snapshot.id}>
                        <button type="button" onClick={() => void restoreSnapshot(snapshot.id)}>
                          {formatTime(snapshot.id.replace(/-/g, (match, offset) => (offset === 10 ? 'T' : match)))}
                        </button>
                      </li>
                    ))}
                  </ul>
                ) : (
                  <p>还没有历史快照。</p>
                )}
              </div>
            )}
            {fileError && <p className="editor-error">{fileError}</p>}
            <textarea
              className="editor-textarea"
              value={content}
              onChange={(event) => {
                setContent(event.target.value)
                setFileStatus('idle')
              }}
              onKeyDown={(event) => {
                if (event.key === 's' && (event.metaKey || event.ctrlKey)) {
                  event.preventDefault()
                  void save()
                }
              }}
              spellCheck={false}
              placeholder="从这里开始写…"
            />
          </>
        ) : (
          <div className="editor-empty">
            <FolderOpen size={28} />
            <h2>选择左侧的文件开始编辑</h2>
            <p>文件夹里的每一个 Markdown 都是作品的一部分，你也可以用别的编辑器直接改。</p>
          </div>
        )}
      </main>

      <AgentPanel workspace={workspace} currentPath={currentPath} onApplied={() => void refreshTree()} />
    </div>
  )
}

