21	const pendingLocal = new Map()
22	let pendingRedisEvents = []
23	
24	function localEvent(message) {
25	  if (!message?.taskId || !message?.event?.type) return
26	  emitter.emit(String(message.taskId), message.event)
27	}
28	
29	function isDeltaEvent(event) {
30	  return typeof event?.delta === 'string'
31	}
