39	  const events = pendingRedisEvents
40	  pendingRedisEvents = []
41	  if (!events.length || !isTaskQueueEnabled()) return
42	  publisher ||= createTaskRedis()
43	  void publisher.publish(TASK_PROGRESS_CHANNEL, JSON.stringify(events)).catch(() => undefined)
44	}
45	
46	function flushTaskEvents(taskId, override = null) {
47	  const list = pendingLocal.get(taskId)
48	  const buffered = list ? [...list] : []
49	  pendingLocal.delete(taskId)
50	  const messages = override ? [...buffered, override] : buffered
51	  if (!messages.length) return
52	  for (const message of messages) localEvent(message)
53	  if (isTaskQueueEnabled()) {
54	    pendingRedisEvents.push(...messages)
55	    if (!publishTimer) {
56	      publishTimer = setTimeout(flushRedisEvents, STREAM_TICK_MS)
57	      publishTimer.unref?.()
58	    }
59	  }
60	}
