    const previous = await readSnapshot(workspace, '正文/第001章_一.md', snapshots[0].id)
    assert.equal(previous.content, '第一版')
    assert.equal((await readWorkspaceText(workspace, '正文/第001章_一.md')).content, '第二版')
  })

