fn create_main_window(app: &tauri::AppHandle, url: &str) -> Result<(), Box<dyn std::error::Error>> {
    let parsed: tauri::Url = url.parse()?;
    let window = WebviewWindowBuilder::new(app, WINDOW_LABEL, WebviewUrl::External(parsed))
        .title("叙事工坊")
        .inner_size(1280.0, 820.0)
        .min_inner_size(960.0, 620.0)
        .center()
        .build()?;
    // 等服务端页面就绪后再显示，避免开窗瞬间的白屏。
    let handle = window.clone();
    window.on_page_load(move |_, payload| {
        if matches!(payload.event(), tauri::webview::PageLoadEvent::Finished) {
            let _ = handle.show();
            let _ = handle.set_focus();
        }
    });
    window.show()?;
    Ok(())
}

