    // 等服务端页面就绪后再显示，避免开窗瞬间的白屏。
    let handle = window.clone();
    window.on_page_load(move |_, payload| {
        if matches!(payload.event(), tauri::webview::PageLoadEvent::Finished) {
            let _ = handle.show();
            let _ = handle.set_focus();
        }
    });
    window.show()?;
    Ok(())
}

